def verify(plan):
    if digest({k:v for k,v in plan.items() if k!='digest'})!=plan['digest']:raise PolicyError('Preparation digest mismatch')
    if datetime.fromisoformat(plan['expires_at'])<datetime.now(timezone.utc):raise PolicyError('Preparation expired; re-review required')
    return plan
